import SwiftUI

/// Storage keys for user profile, travel preferences, and family settings.
enum ProfileKey {
    static let hasCompletedFirstRun = "profile_hasCompletedFirstRun"
    static let userRole = "profile_userRole"
    static let homeCity = "profile_homeCity"
    static let travelTrain = "profile_travelTrain"
    static let travelBus = "profile_travelBus"
    static let travelWalk = "profile_travelWalk"
    static let walkingPace = "profile_walkingPace"
    static let helperMode = "profile_helperMode"
}

/// The first-run question choice: "Is this iPhone for you, or for someone you help?".
enum UserRole: String, CaseIterable, Identifiable {
    case forMe = "forMe"
    case forSomeoneIHelp = "forSomeoneIHelp"

    var id: String { rawValue }

    var title: String {
        switch self {
        case .forMe:
            return "For me"
        case .forSomeoneIHelp:
            return "For someone I help"
        }
    }

    var subtitle: String {
        switch self {
        case .forMe:
            return "I use this iPhone myself. The assistant speaks simply and shows large cards."
        case .forSomeoneIHelp:
            return "I am setting up this iPhone for an older family member. Helper mode enables remote assistance."
        }
    }

    var icon: String {
        switch self {
        case .forMe:
            return "person.fill"
        case .forSomeoneIHelp:
            return "person.2.fill"
        }
    }
}

/// Walking speed preference for journey planning and connection buffers.
enum WalkingPace: String, CaseIterable, Identifiable {
    case leisurely = "leisurely"
    case steady = "steady"
    case brisk = "brisk"

    var id: String { rawValue }

    var title: String {
        switch self {
        case .leisurely:
            return "Leisurely"
        case .steady:
            return "Steady"
        case .brisk:
            return "Brisk"
        }
    }

    var detail: String {
        switch self {
        case .leisurely:
            return "Extra time for platforms and stairs (+8 min buffer)"
        case .steady:
            return "Standard connection times (+4 min buffer)"
        case .brisk:
            return "Quick connections without extra buffer"
        }
    }

    var icon: String {
        switch self {
        case .leisurely:
            return "figure.walk"
        case .steady:
            return "figure.walk.motion"
        case .brisk:
            return "figure.run"
        }
    }
}

/// A trusted family member or caregiver who stays in the loop.
struct TrustedContact: Identifiable, Hashable {
    let id: String
    let name: String
    let relationship: String
    let phone: String
    let isHelper: Bool
    let canReceiveUpdates: Bool
    let note: String
}

import Foundation

/// Local demo fixtures for Profile and Family screens.
///
/// DEMO STAND-IN:
/// This fixture data stands in for backend profile and family sync in the hackathon prototype.
/// All changes are stored locally in @AppStorage and never transmitted over the wire.
enum ProfileFixtures {
    /// Default home city from the hackathon brief.
    static let defaultHomeCity = "Winterthur"

    /// Default walking pace: comfortable for an older user at arm's length.
    static let defaultWalkingPace = WalkingPace.leisurely

    /// Trusted contacts list bundled for the Zurich hackathon demo.
    /// Lena is the daughter and designated family helper.
    static let demoContacts: [TrustedContact] = [
        TrustedContact(
            id: "lena-daughter",
            name: "Lena",
            relationship: "Daughter",
            phone: "+41 79 432 10 98",
            isHelper: true,
            canReceiveUpdates: true,
            note: "Designated helper. Receives trip notifications and can adjust settings."
        ),
        TrustedContact(
            id: "markus-son",
            name: "Markus",
            relationship: "Son",
            phone: "+41 78 876 54 32",
            isHelper: false,
            canReceiveUpdates: true,
            note: "Receives arrival updates when travel plans change."
        )
    ]

    /// Cities available in quick selection.
    static let popularStations = [
        "Winterthur",
        "Zürich HB",
        "Bern",
        "Basel SBB",
        "St. Gallen"
    ]
}

import SwiftUI

/// First-run onboarding screen asking:
/// "Is this iPhone for you, or for someone you help?"
struct FirstRunSheet: View {
    @AppStorage(ProfileKey.hasCompletedFirstRun) private var hasCompletedFirstRun = false
    @AppStorage(ProfileKey.userRole) private var userRoleRaw = UserRole.forMe.rawValue
    @AppStorage(ProfileKey.helperMode) private var helperMode = false

    @Environment(\.dismiss) private var dismiss
    @Environment(\.typeScale) private var type

    @State private var selectedRole: UserRole = .forMe

    var body: some View {
        VStack(alignment: .leading, spacing: 20) {
            header

            ScrollView {
                VStack(alignment: .leading, spacing: 18) {
                    Text("Is this iPhone for you, or for someone you help?")
                        .font(type.display)
                        .foregroundStyle(Theme.textPrimary)
                        .fixedSize(horizontal: false, vertical: true)

                    Text("Orb Agent adapts its voice, display size, and family helper permissions based on who holds this iPhone.")
                        .font(type.body)
                        .foregroundStyle(Theme.textSecondary)
                        .fixedSize(horizontal: false, vertical: true)

                    VStack(spacing: 14) {
                        ForEach(UserRole.allCases) { role in
                            RoleCard(
                                role: role,
                                isSelected: selectedRole == role,
                                onSelect: { selectedRole = role }
                            )
                        }
                    }
                    .padding(.top, 6)

                    safetyNotice
                }
                .padding(.top, 8)
            }
            .scrollBounceBehavior(.basedOnSize)

            Button("Continue") {
                userRoleRaw = selectedRole.rawValue
                if selectedRole == .forSomeoneIHelp {
                    helperMode = true
                }
                hasCompletedFirstRun = true
                dismiss()
            }
            .buttonStyle(BigButtonStyle(kind: .primary))
            .frame(minHeight: max(60, type.control))
            .padding(.bottom, 8)
        }
        .padding(.horizontal, 20)
        .padding(.top, 28)
        .presentationBackground {
            ZStack {
                Rectangle().fill(.ultraThinMaterial)
                Theme.glassSheet
            }
        }
        .presentationCornerRadius(Theme.Radius.xxxl)
        .presentationDragIndicator(.visible)
        .onAppear {
            if let saved = UserRole(rawValue: userRoleRaw) {
                selectedRole = saved
            }
        }
    }

    // MARK: - Subviews

    private var header: some View {
        HStack(spacing: 8) {
            Image(systemName: "sparkles")
                .font(.system(size: 18, weight: .semibold))
                .foregroundStyle(Theme.accentText)
            Text("Orb Agent Setup")
                .font(.system(size: 18, weight: .semibold))
                .foregroundStyle(Theme.accentText)
            Spacer()
            // Demo indicator
            Text("Demo stand-in")
                .font(.system(size: 17, weight: .medium))
                .foregroundStyle(Theme.textMuted)
                .padding(.horizontal, 10)
                .padding(.vertical, 4)
                .background(Capsule().fill(Theme.surfaceChip))
        }
    }

    private var safetyNotice: some View {
        HStack(alignment: .top, spacing: 14) {
            Image(systemName: "checkmark.shield.fill")
                .font(.system(size: 24, weight: .semibold))
                .foregroundStyle(Theme.successText)
                .padding(.top, 2)

            VStack(alignment: .leading, spacing: 4) {
                Text("Owner confirmation guaranteed")
                    .font(type.bodyStrong)
                    .foregroundStyle(Theme.textPrimary)

                Text("No agent or family helper can send messages or create calendar events without on-screen confirmation from the owner.")
                    .font(type.meta)
                    .foregroundStyle(Theme.textMuted)
                    .fixedSize(horizontal: false, vertical: true)
            }
        }
        .padding(18)
        .frame(maxWidth: .infinity, alignment: .leading)
        .background(
            RoundedRectangle(cornerRadius: Theme.Radius.xl, style: .continuous)
                .fill(Theme.surfaceCard)
        )
        .overlay(
            RoundedRectangle(cornerRadius: Theme.Radius.xl, style: .continuous)
                .strokeBorder(Theme.borderGlass, lineWidth: 1)
        )
    }
}

// MARK: - Role Card

private struct RoleCard: View {
    let role: UserRole
    let isSelected: Bool
    let onSelect: () -> Void

    @Environment(\.typeScale) private var type

    var body: some View {
        Button(action: onSelect) {
            HStack(alignment: .top, spacing: 16) {
                Image(systemName: role.icon)
                    .font(.system(size: 28, weight: .semibold))
                    .foregroundStyle(isSelected ? Theme.accentTextStrong : Theme.textSecondary)
                    .frame(width: 44, height: 44)
                    .background(Circle().fill(isSelected ? Theme.accentSoft : Theme.surfaceControl))

                VStack(alignment: .leading, spacing: 6) {
                    HStack {
                        Text(role.title)
                            .font(.system(size: 22, weight: .bold))
                            .foregroundStyle(Theme.textPrimary)
                        Spacer()
                        if isSelected {
                            Image(systemName: "checkmark.circle.fill")
                                .font(.system(size: 24, weight: .semibold))
                                .foregroundStyle(Theme.accent)
                        }
                    }

                    Text(role.subtitle)
                        .font(type.meta)
                        .foregroundStyle(Theme.textMuted)
                        .fixedSize(horizontal: false, vertical: true)
                }
            }
            .padding(18)
            .frame(maxWidth: .infinity, minHeight: 90, alignment: .leading)
            .background(
                RoundedRectangle(cornerRadius: Theme.Radius.xl, style: .continuous)
                    .fill(isSelected ? Theme.accentSoft : Theme.surfaceCard)
            )
            .overlay(
                RoundedRectangle(cornerRadius: Theme.Radius.xl, style: .continuous)
                    .strokeBorder(isSelected ? Theme.accentBorder : Theme.borderGlass, lineWidth: isSelected ? 2 : 1)
            )
        }
        .buttonStyle(.plain)
        .accessibilityAddTraits(isSelected ? [.isSelected, .isButton] : [.isButton])
    }
}

import SwiftUI

enum ProfileTab: String, CaseIterable, Identifiable {
    case profile = "profile"
    case family = "family"

    var id: String { rawValue }

    var title: String {
        switch self {
        case .profile: return "My Profile"
        case .family: return "Family & Helpers"
        }
    }

    var icon: String {
        switch self {
        case .profile: return "person.crop.circle"
        case .family: return "person.2"
        }
    }
}

/// The Profile and Family screen for Orb Agent.
///
/// DEMO STAND-IN:
/// All settings are stored locally in @AppStorage for the hackathon demo.
/// No data is transmitted to the server.
struct ProfileSheet: View {
    var initialTab: ProfileTab = .profile

    @AppStorage(ProfileKey.homeCity) private var homeCity = ProfileFixtures.defaultHomeCity
    @AppStorage(ProfileKey.travelTrain) private var travelTrain = true
    @AppStorage(ProfileKey.travelBus) private var travelBus = true
    @AppStorage(ProfileKey.travelWalk) private var travelWalk = true
    @AppStorage(ProfileKey.walkingPace) private var walkingPaceRaw = ProfileFixtures.defaultWalkingPace.rawValue
    @AppStorage(ProfileKey.userRole) private var userRoleRaw = UserRole.forMe.rawValue
    @AppStorage(ProfileKey.helperMode) private var helperMode = true
    @AppStorage(SettingsKey.largeText) private var largeText = false

    @State private var currentTab: ProfileTab = .profile
    @State private var showFirstRunSheet = false
    @State private var isEditingCity = false
    @State private var tempCity = ""

    @Environment(\.dismiss) private var dismiss
    @Environment(\.typeScale) private var type

    var body: some View {
        VStack(alignment: .leading, spacing: 20) {
            topBar

            tabSelector

            ScrollView {
                VStack(alignment: .leading, spacing: 24) {
                    switch currentTab {
                    case .profile:
                        profileContent
                    case .family:
                        familyContent
                    }
                }
                .padding(.top, 4)
                .padding(.bottom, 16)
            }
            .scrollBounceBehavior(.basedOnSize)

            Button("Done") { dismiss() }
                .buttonStyle(BigButtonStyle(kind: .primary))
                .frame(minHeight: max(60, type.control))
                .padding(.bottom, 8)
        }
        .padding(.horizontal, 20)
        .padding(.top, 28)
        .presentationBackground {
            ZStack {
                Rectangle().fill(.ultraThinMaterial)
                Theme.glassSheet
            }
        }
        .presentationCornerRadius(Theme.Radius.xxxl)
        .presentationDragIndicator(.visible)
        .sheet(isPresented: $showFirstRunSheet) {
            FirstRunSheet()
        }
        .onAppear {
            currentTab = initialTab
        }
    }

    // MARK: - Header & Tab Bar

    private var topBar: some View {
        HStack {
            VStack(alignment: .leading, spacing: 4) {
                Text(currentTab == .profile ? "Profile" : "Family & Helpers")
                    .font(type.display)
                    .foregroundStyle(Theme.textPrimary)
            }
            Spacer()
            // Demo indicator
            Text("Demo stand-in")
                .font(.system(size: 17, weight: .medium))
                .foregroundStyle(Theme.textMuted)
                .padding(.horizontal, 12)
                .padding(.vertical, 6)
                .background(Capsule().fill(Theme.surfaceChip))
        }
    }

    private var tabSelector: some View {
        HStack(spacing: 10) {
            ForEach(ProfileTab.allCases) { tab in
                let selected = currentTab == tab
                Button {
                    currentTab = tab
                } label: {
                    HStack(spacing: 8) {
                        Image(systemName: tab.icon)
                            .font(.system(size: 20, weight: .semibold))
                        Text(tab.title)
                            .font(.system(size: 18, weight: .semibold))
                    }
                    .frame(maxWidth: .infinity, minHeight: max(60, type.control))
                    .foregroundStyle(selected ? Theme.accentTextStrong : Theme.textSecondary)
                    .background(
                        RoundedRectangle(cornerRadius: Theme.Radius.lg, style: .continuous)
                            .fill(selected ? Theme.accentSoft : Theme.surfaceControl)
                    )
                    .overlay(
                        RoundedRectangle(cornerRadius: Theme.Radius.lg, style: .continuous)
                            .strokeBorder(selected ? Theme.accentBorder : Theme.borderInput, lineWidth: selected ? 2 : 1)
                    )
                }
                .buttonStyle(.plain)
                .accessibilityAddTraits(selected ? [.isSelected, .isButton] : [.isButton])
            }
        }
    }

    // MARK: - Profile Content

    private var profileContent: some View {
        VStack(alignment: .leading, spacing: 22) {
            // Setup Role banner
            roleBanner

            // Home Location
            homeSection

            // Travel Modes
            travelModesSection

            // Walking Pace
            walkingPaceSection

            // Large Text Toggle
            accessibilitySection
        }
    }

    private var roleBanner: some View {
        let isForMe = userRoleRaw == UserRole.forMe.rawValue
        return HStack(alignment: .center, spacing: 14) {
            Image(systemName: isForMe ? "person.fill" : "person.2.fill")
                .font(.system(size: 26, weight: .semibold))
                .foregroundStyle(Theme.accentText)
                .frame(width: 48, height: 48)
                .background(Circle().fill(Theme.accentSoft))

            VStack(alignment: .leading, spacing: 2) {
                Text(isForMe ? "Setup: For myself" : "Setup: For someone I help")
                    .font(type.bodyStrong)
                    .foregroundStyle(Theme.textPrimary)
                Text(isForMe ? "Voice and display tailored for direct use" : "Helper mode enabled for Lena")
                    .font(type.meta)
                    .foregroundStyle(Theme.textMuted)
            }

            Spacer()

            Button("Change") {
                showFirstRunSheet = true
            }
            .font(.system(size: 17, weight: .semibold))
            .foregroundStyle(Theme.accentText)
            .padding(.horizontal, 14)
            .frame(minHeight: 44)
            .background(Capsule().fill(Theme.surfaceControl))
        }
        .padding(16)
        .background(
            RoundedRectangle(cornerRadius: Theme.Radius.xl, style: .continuous)
                .fill(Theme.surfaceCard)
        )
        .overlay(
            RoundedRectangle(cornerRadius: Theme.Radius.xl, style: .continuous)
                .strokeBorder(Theme.borderGlass, lineWidth: 1)
        )
    }

    private var homeSection: some View {
        VStack(alignment: .leading, spacing: 10) {
            Text("Home Location")
                .font(.system(size: 20, weight: .bold))
                .foregroundStyle(Theme.textPrimary)

            Text("Default starting station for connection plans and return journeys.")
                .font(type.meta)
                .foregroundStyle(Theme.textMuted)

            HStack(spacing: 12) {
                Image(systemName: "house.fill")
                    .font(.system(size: 24, weight: .semibold))
                    .foregroundStyle(Theme.accentText)

                if isEditingCity {
                    TextField("Enter station", text: $tempCity)
                        .font(type.bodyStrong)
                        .foregroundStyle(Theme.textPrimary)
                        .autocorrectionDisabled()
                        .onSubmit {
                            if !tempCity.trimmingCharacters(in: .whitespaces).isEmpty {
                                homeCity = tempCity.trimmingCharacters(in: .whitespaces)
                            }
                            isEditingCity = false
                        }

                    Button("Save") {
                        if !tempCity.trimmingCharacters(in: .whitespaces).isEmpty {
                            homeCity = tempCity.trimmingCharacters(in: .whitespaces)
                        }
                        isEditingCity = false
                    }
                    .font(.system(size: 17, weight: .bold))
                    .foregroundStyle(Theme.accentText)
                } else {
                    Text(homeCity)
                        .font(.system(size: 22, weight: .bold))
                        .foregroundStyle(Theme.textPrimary)

                    Spacer()

                    Button {
                        tempCity = homeCity
                        isEditingCity = true
                    } label: {
                        Text("Edit")
                            .font(.system(size: 17, weight: .semibold))
                            .foregroundStyle(Theme.accentText)
